function App() {
  const [text, setText] = useState('');
  const [list, setList] = useState([]);
  const [isPending, startTransition] = useTransition();
  const onChange = (e) => {
    const value = e.target.value;
    setText(value); // urgent: keep input responsive
    startTransition(() => {
      // non-urgent: heavy work React can interrupt
      const items = Array.from({ length: 5000 }, (_, i) => `${value} #${i}`);
      setList(items);
    });
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={onChange} placeholder="Type fast..." />
      {isPending && <span style={{ marginLeft: 8, color: '#999' }}>updating…</span>}
      <p>{list.length} rows generated</p>
    </div>
  );
}

