let external = 0;
function App() {
  const [count, setCount] = useState(external);
  useEffect(() => {
    external += 1;        // runs in the commit phase, after render
    setCount(external);
  }, []);                 // once per mount
  const [, setTick] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>External: {count}</h2>
      <button onClick={() => setTick(t => t + 1)}>Re-render</button>
    </div>
  );
}

function App() {
  const all = Array.from({ length: 10000 }, (_, i) => `Row ${i}`);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);
  const isStale = query !== deferredQuery;
  const results = all.filter(r => r.includes(deferredQuery));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Filter rows..." />
      <p style={{ opacity: isStale ? 0.5 : 1 }}>{results.length} matches</p>
    </div>
  );
}
